const VC_FIRST = ['Jordan', 'Riley', 'Casey', 'Avery', 'Morgan', 'Quinn', 'Skyler', 'Rowan'];
const VC_LAST = ['Blake', 'Ellis', 'Harper', 'Nguyen', 'Okafor', 'Santos', 'Vega', 'Walsh'];
let __vcSeq = 0;
const vcMakeCreated = n => {
  const now = new Date().toISOString();
  return Array.from({
    length: n
  }, (_, i) => {
    const first = VC_FIRST[(__vcSeq + i) % VC_FIRST.length];
    const last = VC_LAST[(__vcSeq * 3 + i) % VC_LAST.length];
    return {
      id: uid('cp'),
      externalUid: `urn:uuid:imported-${Date.now()}-${i}`,
      type: 'Person',
      displayName: null,
      notes: 'Imported from vCard.',
      archived: null,
      createdAt: now,
      updatedAt: now,
      person: {
        firstName: first,
        lastName: last,
        dateOfBirth: null,
        sex: null,
        title: null,
        company: null
      },
      addresses: [],
      emails: [{
        id: uid('e'),
        label: 'Home',
        isPrimary: true,
        value: `${first}.${last}`.toLowerCase() + '@example.com'
      }],
      phones: []
    };
  });
};
const simulateImport = (file, rows, outcome) => {
  if (outcome === 'rejected') return {
    rejected: 'This file has more than the 5,000-contact limit (MaxVCardEntries). Split it into smaller files and import each.'
  };
  // A file whose name looks like an Odyssey export round-trips: every entry
  // matches an existing UID, so all update and none are created (idempotent).
  if (/^odyssey-contacts/i.test(file.name || '')) {
    const ids = rows.map(r => r.id);
    return {
      result: {
        createdCount: 0,
        updatedCount: ids.length,
        skipped: []
      },
      createdRows: [],
      updatedIds: ids
    };
  }
  const created = vcMakeCreated(6);
  __vcSeq += 6;
  const updatedIds = rows.slice(0, 2).map(r => r.id);
  const skipped = outcome === 'clean' ? [] : [{
    reason: 'Missing a usable name (no FN, N, or ORG)',
    count: 3,
    sampleNames: ['(no name)', 'vCard entry 14', 'vCard entry 31']
  }, {
    reason: 'Email address is not valid',
    count: 2,
    sampleNames: ['Taylor Reed', 'Harbor Dental Group']
  }, {
    reason: 'Name exceeds 128 characters',
    count: 1,
    sampleNames: ['Aaaaaaaaaaaaaaaaaaaaaaaaaaaa…']
  }, {
    reason: 'External ID already in use by another contact',
    count: 1,
    sampleNames: ['Michael Chen']
  }];
  return {
    result: {
      createdCount: created.length,
      updatedCount: updatedIds.length,
      skipped
    },
    createdRows: created,
    updatedIds
  };
};

