        total: all.length,
        active: all.filter(c => !c.archived).length,
        countsByStatus: counts,
        typeRows: D.contractTypes.map(t2 => ({
          key: t2.key,
          label: t2.label,
          icon: t2.icon,
          color: t2.color,
          soft: t2.soft,
          count: byType[t2.key] || 0
        })).filter(r => r.count > 0)
